export type Emoji = {
  char: string;
  /** The official Unicode name, shown on hover. */
  name: string;
  /** Name plus CLDR keywords, lowercased, for matching. */
  search: string;
};

export type EmojiGroup = { name: string; emojis: Emoji[] };

let parsed: EmojiGroup[] | null = null;

/** The full set, parsed once per session. */
export function getEmojiGroups(): EmojiGroup[] {
  parsed ??= GROUPS.map(([name, blob]) => ({
    name,
    emojis: blob.split("\n").map(record => {
      const space = record.indexOf(" ");
      const [emojiName, keywords] = record.slice(space + 1).split("\t");
      return {
        char: record.slice(0, space),
        name: emojiName,
        search: keywords ? `${emojiName} ${keywords}`.toLowerCase() : emojiName.toLowerCase(),
      };
    }),
  }));
  return parsed;
}
